   $$biologie-havo-2022-i-alg-doet-oliepalm-na-vraag1.png$$, $$1p 1 Geef een ander argument waarom gebruik van olie van oliepalmplantages in Zuidoost-Azië vanuit ecologisch oogpunt minder duurzaam is dan gebruik van in Nederland geproduceerde algen-olie.$$, array['12f22f4a-def8-4af6-92eb-2a2365e49a9b', '648c97c2-06d1-4a58-9ce0-6202d134b396', '5f7d4f02-dba3-4612-9643-d160ba655ef8']::uuid[]),
